type Handler = (e: { type: string }) => void;

class Emitter {
  private handlers: { [key: string]: Handler[] } = {};

  on(t: string, h: Handler): void {
    if (!this.handlers[t]) {
      this.handlers[t] = [];
    }
    this.handlers[t].push(h);
  }

  emit(t: string): void {
    const eventHandlers = this.handlers[t];
    if (eventHandlers) {
      eventHandlers.forEach(h => h({ type: t }));
    }
  }
}
```

