To implement infinite scrolling in a React Native FlatList, I will use the `onEndReached` prop to detect when the user has reached the end of the list and then fetch more data to append to the existing list. An important edge case to consider is setting an appropriate `onEndReachedThreshold` value to prevent excessive calls to the data fetching function as the user scrolls near the end of the list. This threshold should be set to a value that ensures the data is fetched before the user reaches the very end of the list content.

ANSWER:

```jsx
import React, { useState, useEffect } from 'react';
import { FlatList, Text, View } from 'react-native';

const InfiniteScrollList = () => {
  const [data, setData] = useState([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchData();
  }, [page]);

  const fetchData = async () => {
    if (loading) return;
    setLoading(true);
    // Simulate fetching data from an API
    const newData = await new Promise(resolve =>
      setTimeout(() => resolve(Array.from({ length: 10 }, (_, i) => ({ key: `${page}-${i}`, value: `Item ${page}-${i}` })), 1000)
    );
    setData(prevData => [...prevData, ...newData]);
    setLoading(false);
  };

  const renderFooter = () => {
    if (!loading) return null;
    return (
      <View style={{ paddingVertical: 20, borderTopWidth: 1, borderTopColor: '#ccc' }}>
        <Text>Loading...</Text>
      </View>
    );
  };

  return (
    <FlatList
      data={data}
      renderItem={({ item }) => (
        <View style={{ padding: 20, borderBottomWidth: 1, borderBottomColor: '#ccc' }}>
          <Text>{item.value}</Text>
        </View>
      )}
      keyExtractor={item => item.key}
      onEndReached={() => setPage(prevPage => prevPage + 1)}
      onEndReachedThreshold={0.5}
      ListFooterComponent={renderFooter}
    />
  );
};

export default InfiniteScrollList;
```

